using System;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Globalization;using System.Collections.Generic;
namespace BeamScheduleFormatter {
static class StaadDisplacements {
 internal static double Unit(string unit){switch((unit??"").ToLowerInvariant()){case "m":case "meter":case "metre":return 1;case "mm":case "millimeter":return .001;case "cm":case "centimeter":return .01;case "in":case "inch":case "inches":return .0254;case "ft":case "feet":case "foot":return .3048;default:throw new Exception("Select an explicit length/displacement unit.");}}
 internal static double Number(string value){double result;if(!double.TryParse((value??"").Trim().Replace('D','E').Replace('d','E'),NumberStyles.Float,CultureInfo.InvariantCulture,out result)||!WindTin.Finite(result))throw new Exception("Invalid STAAD number: "+value+". Use decimal points without thousands separators.");return result;}
 internal static int Id(string text){int result;if(!int.TryParse(text,out result)||result<=0)throw new Exception("Invalid STAAD node/member ID: "+text);return result;}
 internal static string[] Fields(string line){char separator=line.Contains("\t")?'\t':line.Contains(",")?',':' ';if(separator==' ')return Regex.Split(line.Trim(),@"\s+");var values=new List<string>();var field=new StringBuilder();bool quote=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(quote&&i+1<line.Length&&line[i+1]=='"'){field.Append('"');i++;}else quote=!quote;}else if(c==separator&&!quote){values.Add(field.ToString().Trim());field.Length=0;}else field.Append(c);}if(quote)throw new Exception("Unclosed CSV quote.");values.Add(field.ToString().Trim());return values.ToArray();}
 static string Key(string text){return Regex.Replace((text??"").ToLowerInvariant(),@"[\s_\-]+","");}
 static bool Axis(string key,string axis){return key==axis||new[]{"mm","cm","m","in","ft"}.Any(unit=>key==axis+unit)||key.StartsWith(axis+"coord")||key.StartsWith("global"+axis)||key.StartsWith(axis+"(")||key.StartsWith(axis+"[")||key=="d"+axis||key.StartsWith("d"+axis+"(")||key.StartsWith(axis+"trans")||key.StartsWith(axis+"translation")||key.StartsWith(axis+"displacement");}
 internal static List<string[]> Rows(string text){return (text??"").Replace("\r","").Split('\n').Where(line=>!string.IsNullOrWhiteSpace(line)).Select(Fields).ToList();}
 internal static void AddNode(BeamDeflectionData data,BeamNode node){BeamNode old;if(data.Nodes.TryGetValue(node.Id,out old)){if(BeamDeflection.Distance(old,node)>1e-8)throw new Exception("Conflicting coordinates for node "+node.Id);return;}data.Nodes.Add(node.Id,node);}
 internal static void AddMember(BeamDeflectionData data,BeamMember member){BeamMember old;if(data.Members.TryGetValue(member.Id,out old)){if(!(old.A==member.A&&old.B==member.B||old.A==member.B&&old.B==member.A))throw new Exception("Conflicting incidences for member "+member.Id);return;}data.Members.Add(member.Id,member);}
 internal static void AddDisplacement(BeamDeflectionData data,BeamDisplacement row){var old=data.Displacements.FirstOrDefault(d=>d.Node==row.Node&&d.Case.Equals(row.Case,StringComparison.OrdinalIgnoreCase));if(old!=null){if(Math.Abs(old.X-row.X)+Math.Abs(old.Y-row.Y)+Math.Abs(old.Z-row.Z)>1e-10)throw new Exception("Conflicting displacement for node "+row.Node+", case "+row.Case);return;}data.Displacements.Add(row);}
 internal static void Coordinates(BeamDeflectionData data,string text,string unit){var rows=Rows(text);double factor=Unit(unit);int header=rows.FindIndex(r=>r.Any(h=>Key(h)=="node"||Key(h)=="nodeid"||Key(h)=="joint")&&r.Any(h=>Axis(Key(h),"x"))&&r.Any(h=>Axis(Key(h),"z")));if(header<0)throw new Exception("Coordinate table needs Node, X, Y, Z headers.");var columnNames=rows[header];int id=Array.FindIndex(columnNames,x=>new[]{"node","nodeid","joint"}.Contains(Key(x))),xcol=Array.FindIndex(columnNames,x=>Axis(Key(x),"x")),ycol=Array.FindIndex(columnNames,x=>Axis(Key(x),"y")),zcol=Array.FindIndex(columnNames,x=>Axis(Key(x),"z"));if(ycol<0)throw new Exception("Missing coordinate Y column.");foreach(int col in new[]{xcol,ycol,zcol}){string declared=DetectUnit(columnNames[col]);if(declared!=null&&Math.Abs(Unit(declared)-factor)>1e-12)throw new Exception("Selected geometry unit conflicts with coordinate header "+columnNames[col]);}for(int r=header+1;r<rows.Count;r++){var p=rows[r];if(p.Length<=new[]{id,xcol,ycol,zcol}.Max())throw new Exception("Incomplete node coordinate row.");if(Key(p[id])==Key(columnNames[id]))continue;AddNode(data,new BeamNode{Id=Id(p[id]),X=Number(p[xcol])*factor,Y=Number(p[ycol])*factor,Z=Number(p[zcol])*factor});}}
 internal static void Members(BeamDeflectionData data,string text){var rows=Rows(text);int header=rows.FindIndex(r=>r.Any(h=>new[]{"member","beam","memberid"}.Contains(Key(h)))&&r.Any(h=>new[]{"start","startnode","nodea","node1","jointi"}.Contains(Key(h))));if(header<0)throw new Exception("Member table needs Member, StartNode, EndNode headers.");var columnNames=rows[header];int id=Array.FindIndex(columnNames,x=>new[]{"member","beam","memberid"}.Contains(Key(x))),a=Array.FindIndex(columnNames,x=>new[]{"start","startnode","nodea","node1","jointi"}.Contains(Key(x))),b=Array.FindIndex(columnNames,x=>new[]{"end","endnode","nodeb","node2","jointj"}.Contains(Key(x)));if(b<0)throw new Exception("Missing member end-node column.");for(int r=header+1;r<rows.Count;r++){var p=rows[r];if(p.Length<=Math.Max(id,Math.Max(a,b)))throw new Exception("Incomplete member incidence row.");if(Key(p[id])==Key(columnNames[id]))continue;AddMember(data,new BeamMember{Id=Id(p[id]),A=Id(p[a]),B=Id(p[b])});}}
 internal static void Displacements(BeamDeflectionData data,string text,string unit){var rows=Rows(text);double factor=Unit(unit);int header=rows.FindIndex(r=>r.Any(h=>new[]{"node","nodeid","joint"}.Contains(Key(h)))&&r.Any(h=>new[]{"l/c","case","loadcase","load"}.Contains(Key(h))));if(header<0)throw new Exception("Displacement table needs Node, L/C, X/Y/Z translation headers.");var columnNames=rows[header];int id=Array.FindIndex(columnNames,x=>new[]{"node","nodeid","joint"}.Contains(Key(x))),lc=Array.FindIndex(columnNames,x=>new[]{"l/c","case","loadcase","load"}.Contains(Key(x))),xcol=Array.FindIndex(columnNames,x=>Axis(Key(x),"x")),ycol=Array.FindIndex(columnNames,x=>Axis(Key(x),"y")),zcol=Array.FindIndex(columnNames,x=>Axis(Key(x),"z"));if(new[]{xcol,ycol,zcol}.Any(c=>c<0))throw new Exception("Missing X/Y/Z translation columns; rotations are not translations.");foreach(int col in new[]{xcol,ycol,zcol}){string detected=DetectUnit(columnNames[col]);if(detected!=null&&Math.Abs(Unit(detected)-factor)>1e-12)throw new Exception("Selected displacement unit conflicts with table header "+columnNames[col]);}string lastNode="",lastCase="";for(int r=header+1;r<rows.Count;r++){var p=rows[r];if(p.Length<=new[]{id,lc,xcol,ycol,zcol}.Max())throw new Exception("Incomplete displacement row "+(r+1));if(Key(p[id])==Key(columnNames[id]))continue;string node=p[id]==""?lastNode:p[id],load=p[lc]==""?lastCase:p[lc];if(load=="")throw new Exception("Missing load case.");AddDisplacement(data,new BeamDisplacement{Node=Id(node),Case=load,X=Number(p[xcol])*factor,Y=Number(p[ycol])*factor,Z=Number(p[zcol])*factor});lastNode=node;lastCase=load;}}
 internal static string DetectUnit(string text){string t=(text??"").ToUpperInvariant();if(Regex.IsMatch(t,@"MILLIMET|\bMM\b"))return "mm";if(Regex.IsMatch(t,@"CENTIMET|\bCM\b"))return "cm";if(Regex.IsMatch(t,@"\bINCH(?:ES)?\b|\bIN\b"))return "in";if(Regex.IsMatch(t,@"\bFEET\b|\bFOOT\b|\bFT\b"))return "ft";if(Regex.IsMatch(t,@"\bMET(?:ER|RE)S?\b|\bM\b"))return "m";return null;}
 internal static void Model(BeamDeflectionData data,string text,string defaultUnit){string mode="";double factor=Unit(defaultUnit);foreach(string raw in (text??"").Replace("\r","").Split('\n')){string line=Regex.Replace(raw,@"^\s*\d+\.\s+","").Trim();if(line==""||line.StartsWith("*"))continue;if(Regex.IsMatch(line,@"^SET\s+Z\s+UP",RegexOptions.IgnoreCase)){data.ZUp=true;continue;}if(line.StartsWith("UNIT ",StringComparison.OrdinalIgnoreCase)){string unit=DetectUnit(line);if(unit!=null)factor=Unit(unit);continue;}if(line.StartsWith("JOINT COORDINATES",StringComparison.OrdinalIgnoreCase)){mode="nodes";line=line.Substring(17).Trim();}else if(line.StartsWith("MEMBER INCIDENCES",StringComparison.OrdinalIgnoreCase)){mode="members";line=line.Substring(17).Trim();}else if(!Regex.IsMatch(line,@"^\d")){if(mode!=""&&line.StartsWith("REPEAT",StringComparison.OrdinalIgnoreCase))throw new Exception("Expanded node coordinates are required; STAAD REPEAT geometry is not expanded automatically.");mode="";continue;}if(mode==""||line=="")continue;foreach(string statement in line.Split(';')){var p=Regex.Split(statement.Trim(),@"\s+");if(p.Length==1&&p[0]=="")continue;if(mode=="nodes"){if(p.Length!=4)throw new Exception("Unsupported joint-coordinate statement. Export expanded Node/X/Y/Z table.");AddNode(data,new BeamNode{Id=Id(p[0]),X=Number(p[1])*factor,Y=Number(p[2])*factor,Z=Number(p[3])*factor});}else{if(p.Length!=3)throw new Exception("Unsupported member incidence statement.");AddMember(data,new BeamMember{Id=Id(p[0]),A=Id(p[1]),B=Id(p[2])});}}}}
 internal static void Anl(BeamDeflectionData data,string text,string geometryUnit,string displacementUnit){var model=new BeamDeflectionData();bool complete=true;try{Model(model,text,geometryUnit);}catch(Exception){complete=false;}if(complete){foreach(var node in model.Nodes.Values)AddNode(data,node);foreach(var member in model.Members.Values)AddMember(data,member);data.ZUp=model.ZUp;}double factor=Unit(displacementUnit);bool reading=false;int lastNode=0;foreach(string line in (text??"").Replace("\r","").Split('\n')){if(Regex.IsMatch(line,@"(?:JOINT|NODE)\s+DISPLACEMENT",RegexOptions.IgnoreCase)){reading=true;string unit=DetectUnit(line);if(unit!=null&&Math.Abs(Unit(unit)-factor)>1e-12)throw new Exception("ANL displacement unit is "+unit+"; select the matching unit.");continue;}if(!reading)continue;string declared=DetectUnit(line);if(declared!=null&&Regex.IsMatch(line,@"UNIT|TRANS|METER|METRE|RADIANS",RegexOptions.IgnoreCase)&&!Regex.IsMatch(line,@"^\s*\d")&&Math.Abs(Unit(declared)-factor)>1e-12)throw new Exception("ANL translation units conflict with selected unit.");if(Regex.IsMatch(line,@"JOINT\s+REACTION|MEMBER\s+(?:END\s+)?FORCE|MAXIMUM\s+DISPLACEMENT|SUPPORT\s+REACTION",RegexOptions.IgnoreCase)){reading=false;continue;}string[] p=Regex.Split(line.Trim(),@"\s+");int node,load,offset;if((p.Length>=8||p.Length==5)&&int.TryParse(p[0],out node)&&int.TryParse(p[1],out load)&&load>0){offset=2;lastNode=node;}else if((p.Length>=7||p.Length==4)&&lastNode>0&&int.TryParse(p[0],out load)){node=lastNode;offset=1;}else continue;if(node<=0||load<=0)throw new Exception("Invalid ANL node/load ID.");AddDisplacement(data,new BeamDisplacement{Node=node,Case=load.ToString(CultureInfo.InvariantCulture),X=Number(p[offset])*factor,Y=Number(p[offset+1])*factor,Z=Number(p[offset+2])*factor});}if(data.Displacements.Count==0)throw new Exception("No supported JOINT DISPLACEMENTS table found in ANL. Include PRINT JOINT DISPLACEMENTS or export the node displacement table.");}
}
}
